//! Actual passive noscript text replacement and retirement retain native records.
use super::*;
fn fixture(raw:bool)->(Document,Forms,Page){let source="<body><div id=mount><noscript id=host><span id=fake>Fallback</span><script>window.bad=1;</script></noscript></div><div id=protected><input id=field value=seed><noscript id=other>Other</noscript></div><p id=out>Real</p>";let mut d=if raw{crate::html::parse_loaded_document_with_scripting(source,true,&||Ok(())).unwrap()}else{crate::html::parse(source)};d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn noscript_text_content_exact_units_null_clear_and_parent_retirement_have_actual_records(){
 let(mut d,mut f,mut p)=fixture(true);run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),mount=document.getElementById('mount'),old=host.firstChild,oldData=old.data,raw='\udfff\ud800<img id=fake src=missing><script>window.bad=2;</script>&amp;',watch=new MutationObserver(function(){});watch.observe(host,{childList:true,characterData:true,subtree:true});watch.observe(mount,{childList:true});host.textContent=raw;var text=host.firstChild,records=watch.takeRecords();if(text===old||text.nodeType!==3||text.ownerDocument!==document||text.parentNode!==host||text.data!==raw||host.textContent!==raw||host.innerHTML!==raw||raw.charCodeAt(0)!==57343||raw.charCodeAt(1)!==55296||old.parentNode!==null||old.data!==oldData||records.length!==1||records[0].target!==host||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text||document.getElementById('fake')!==null||window.bad!==undefined)throw 'actual passive text replacement';host.textContent=null;records=watch.takeRecords();if(host.firstChild!==null||host.textContent!==''||host.childNodes.length||text.parentNode!==null||text.data!==raw||records.length!==1||records[0].removedNodes[0]!==text||records[0].addedNodes.length)throw 'nullable content clears';host.textContent=raw;var replacement=host.firstChild;records=watch.takeRecords();if(replacement===text||records.length!==1||records[0].addedNodes[0]!==replacement||records[0].removedNodes.length)throw 'new actual Text after clear';mount.textContent='Safe';records=watch.takeRecords();if(host.parentNode!==null||host.firstChild!==replacement||replacement.parentNode!==host||replacement.data!==raw||records.length!==1||records[0].target!==mount||records[0].removedNodes[0]!==host||records[0].addedNodes[0]!==mount.firstChild||mount.firstChild.nodeType!==3||mount.textContent!=='Safe'||document.getElementById('host')!==null||document.getElementById('fake')!==null||document.querySelectorAll('script').length||window.bad!==undefined)throw 'passive host parent retirement';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_content_nontext_and_native_control_retirement_refuse_atomically(){
 for raw in [false,true]{let(mut d,mut f,mut p)=fixture(raw);run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),mount=document.getElementById('mount'),guarded=document.getElementById('protected'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let value=f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>();
  let codes=if raw{vec!["guarded.textContent='blocked';"]}else{vec!["host.textContent='blocked';","mount.textContent='blocked';"]};for code in codes{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("textContent")||error.contains("text container"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>(),value);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||window.bad!==undefined)throw 'protected retirement unchanged';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());}
}
#[test]
fn noscript_text_content_quota_refusals_preserve_saved_text_records_then_recover(){
 let(mut d,mut f,mut p)=fixture(true);run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,watch=new MutationObserver(function(){});watch.observe(host,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let error=p.runtime.execute("host.textContent='replacement';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();let e=error.to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||old.parentNode!==host||watch.takeRecords().length)throw 'content refusal atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"host.textContent='Recovered';var records=watch.takeRecords();if(host.firstChild===old||old.parentNode!==null||host.textContent!=='Recovered'||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==host.firstChild)throw 'fresh text replacement recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
